def count_nums(arr):
    if not arr:
        return 0
    count = 0
    for num in arr:
        digit_sum = sum(int(digit) for digit in str(num))
        # Account for the sign of the first digit for negative numbers
        if num < 0:
            digit_sum += int(str(num)[1]) * -1
        if digit_sum > 0:
            count += 1
    return count
